import sys
import time
from concurrent.futures import ThreadPoolExecutor

import pytest


class Bad(Exception):
    def __init__(self, n: int) -> None:
        self.n = n


def check(x: int) -> int:
    if x % 2 == 1:
        raise Bad(x)
    return x


def all_even(xs: list[int]) -> list[int]:
    """Run check on every element of xs in parallel using a thread pool.

    Returns the checked values in input order. If any element is bad,
    raises the Bad of the lowest-index bad element, regardless of which
    thread finishes first.
    """
    if not xs:
        return []
    with ThreadPoolExecutor(max_workers=min(32, len(xs))) as pool:
        # map yields results in input order, so iterating re-raises the
        # exception of the lowest-index failing element, not the first
        # one to finish.
        return list(pool.map(check, xs))


def test_all_even_returns_values_in_order() -> None:
    assert all_even([2, 4, 6, 0, -8]) == [2, 4, 6, 0, -8]


def test_all_even_empty() -> None:
    assert all_even([]) == []


def test_all_even_single_bad() -> None:
    with pytest.raises(Bad) as ei:
        all_even([2, 4, 7, 8])
    assert ei.value.n == 7


def test_all_even_lowest_index_bad_wins() -> None:
    with pytest.raises(Bad) as ei:
        all_even([2, 3, 4, 5, 7])
    assert ei.value.n == 3


def test_all_even_lowest_index_wins_even_if_it_finishes_last(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    real_check = check

    def slow_first_bad(x: int) -> int:
        # The lowest-index bad element (9) is the slowest to finish.
        if x == 9:
            time.sleep(0.3)
        return real_check(x)

    monkeypatch.setattr(sys.modules[__name__], "check", slow_first_bad)
    with pytest.raises(Bad) as ei:
        all_even([2, 9, 4, 3, 5])
    assert ei.value.n == 9


def test_all_even_lowest_index_not_lowest_value(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    real_check = check

    def slow_check(x: int) -> int:
        if x == 11:
            time.sleep(0.2)
        return real_check(x)

    monkeypatch.setattr(sys.modules[__name__], "check", slow_check)
    # Index 0 is 11 (bad, slow); index 2 is 1 (bad, fast, smaller value).
    with pytest.raises(Bad) as ei:
        all_even([11, 2, 1])
    assert ei.value.n == 11


def test_all_even_runs_in_parallel(monkeypatch: pytest.MonkeyPatch) -> None:
    real_check = check

    def sleepy(x: int) -> int:
        time.sleep(0.2)
        return real_check(x)

    monkeypatch.setattr(sys.modules[__name__], "check", sleepy)
    xs = [2, 4, 6, 8]
    start = time.monotonic()
    assert all_even(xs) == xs
    elapsed = time.monotonic() - start
    assert elapsed < 0.2 * len(xs) * 0.75
